  "k206": "お昼寝",
  "k207": "眠くなった子から順に。眠っているあいだも、こまめにようすを見ています。",
  "k208": "<b>おやつ</b>",
  "k209": "<b>好きなあそび</b>",
  "k210": "順次降園",
  "k211": "その日のごようすを、おむかえのときにおつたえします。",
  "k212": "<b>延長保育・補食</b>",
  "k213": "<b>閉園</b>",
  "k214": "3・4・5歳",
  "k215": "みんなと、じぶんで",
  "k216": "友だちといっしょに過ごす時間が増えます。年長は就学に向けて、少しずつ生活のリズムを整えていきます。",
  "k217": "自分でしたくをして、好きなあそびを始めます。",
  "k218": "朝の会",
  "k219": "あいさつ、うた、今日することの確認。",
  "k220": "きょうの活動",
  "k221": "外あそび、制作、リズム、絵本。日によって変わります。",
  "k222": "配膳のお手伝いも、こどもたちの仕事です。",
  "k223": "午睡・休息",
  "k224": "年長は少しずつ短くし、静かな活動の時間に変えていきます。",
  "k225": "<b>好きなあそび・園庭</b>",
  "k226": "※ 時間はおおよその目安です。その日の天気やこどもたちのようすで前後します。",
  "k227": "大切にしている時間",
  "k228": "一日のなかに、",
  "k229": "こんな時間があります",
  "k230": "特別なプログラムではなく、毎日の生活とあそびのなかに置いている時間です。",
  "k231": "ことばのじかん",
  "k232": "日本語と、おうちのことば。どちらも大切にします。ポルトガル語・英語・タガログ語を話す職員が、その子の分かることばで声をかけます。",
  "k233": "そとのじかん",
  "k234": "天気のよい日は毎日そとへ。園庭であそぶ日と、近くの公園までお散歩に出る日があります。",
  "k235": "たべるじかん",
  "k236": "給食もおやつも自園調理です。アレルギーはもちろん、ご家庭の食文化にも合わせられます。",
  "k237": "つくるじかん",
  "k238": "絵の具、のり、はさみ、粘土。上手に作ることより、やってみたい気持ちが続くことを大事にしています。",
  "k239": "よむじかん",
  "k240": "毎日の読み聞かせ。日本語の絵本のほかに、おうちのことばの絵本も置いています。",
  "k241": "じぶんでのじかん",
  "k242": "着替え、手あらい、はみがき、片づけ。先まわりして手を出さず、できるまで待ちます。",
  "k243": "かみのての保育（大切にしていること）を見る →",
  "k244": "年間行事",
  "k245": "一年のたのしみ",
  "k246": "季節を感じる行事と、毎月かならずあること。<br class=\"x-br\">保護者の方にお越しいただく行事は、土曜日を中心にしています。",
  "k247": "毎月：誕生会",
  "k248": "毎月：避難訓練",
  "k249": "毎月：身体測定",
  "k250": "毎月：園だより・クラスだより",
  "k251": "年2回：内科健診・歯科健診",
  "k252": "4<small>月</small>",
  "k253": "入園式・進級式",
  "k254": "こいのぼり作り",
  "k255": "5<small>月</small>",
  "k256": "こどもの日のつどい",
  "k257": "親子遠足",
  "k258": "6<small>月</small>",
  "k259": "歯科健診",
