  "k282": "書きぞめ",
  "k283": "2<small>月</small>",
  "k284": "節分・豆まき",
  "k285": "生活発表会",
  "k286": "3<small>月</small>",
  "k287": "ひなまつり",
  "k288": "お別れ遠足",
  "k289": "卒園式",
  "k290": "<b>行事のお知らせは、やさしい日本語とポルトガル語・英語でおとどけします。</b> 持ちものや当日の流れは、ことばのちがいでいちばん行きちがいの起きやすいところです。おたよりは翻訳をつけ、必要なときは職員が直接おつたえします。",
  "k291": "※ このページの一日の流れと行事は、一般的な保育園の例をもとにした仮のものです。取材のときにうかがって、かみのて保育園の実際の内容に差し替えます。",
  "k292": "わたしたちの考えていること",
  "k293": "こどもの「やってみたい」を、<br class=\"x-br\">まんなかに。",
  "k294": "おとなの都合で一日を組み立てるのではなく、こどもがいま何をしたいのかを真ん中に置きます。できるまで待ち、できた瞬間をいっしょに喜ぶ。その積み重ねが、これから先の「自分でやってみよう」につながると考えています。",
  "k295": "保育方針",
  "k296": "理念を、毎日のかたちに",
  "k297": "理念だけでは日々は動きません。<br class=\"x-br\">かみのてでは、次の3つを約束としています。",
  "k298": "一人ひとりのリズムを、こちらが合わせる",
  "k299": "眠る時間も、食べる量も、できるようになる順番も、その子によってちがいます。園の時間割に合わせてもらうのではなく、こちらが合わせにいきます。",
  "k300": "ことばと文化のちがいを、前提にする",
  "k301": "日本語が家庭のことばでない子がいるのは、かみのてでは特別なことではありません。ちがいがあることを前提に、保育も、ご家庭とのやりとりも組み立てます。",
  "k302": "ご家庭と、同じ側に立つ",
  "k303": "園とご家庭は、こどもを挟んで向かい合うのではなく、同じ側からこどもを見る関係だと考えています。困りごとは、どちらの責任かを決めずに、いっしょに考えます。",
  "k304": "日々の関わり方（かみのての保育）を見る →",
  "k305": "保育目標",
  "k306": "こんな子に、",
  "k307": "育ってほしいと思っています",
  "k308": "よく食べ、よく眠り、よくあそぶ子",
  "k309": "からだの土台がいちばん先です。生活のリズムが整っていることを、何よりも大事にします。",
  "k310": "自分で考えて、やってみる子",
  "k311": "正しくできることより、やってみようと思えること。失敗しても、もう一度やれることを大切にします。",
  "k312": "ちがいを、おもしろがれる子",
  "k313": "肌の色、ことば、食べるもの。ちがいは分けるものではなく、知るとおもしろいものだと感じてほしいと思っています。",
  "k314": "自分の気持ちを、ことばにできる子",
  "k315": "うれしい、いやだ、たすけて。伝えられることが、その子を守ります。ことばが育つ途中の子には、おとなが代わりにことばにします。",
  "k316": "園長メッセージ",
  "k317": "ごあいさつ",
  "k318": "かみのて保育園は、はたらくご家庭のとなりで、こどもの一日をおあずかりする園です。",
  "k319": "朝早くから夜おそくまで、送り迎えの時間はご家庭によってさまざまです。日本語でのやりとりに不安のある方もいらっしゃいます。そのどれも、こどもをあずけにくい理由にはならない園でありたいと思っています。",
  "k320": "こどもは、大人が思っているよりずっと自分で育っていきます。わたしたちの仕事は、その邪魔をしないことと、育つのに必要なものをそろえておくことだと考えています。安心して過ごせる場所、信じて待ってくれる大人、そして、ちがう誰かと出会える毎日です。",
  "k321": "園のことは、いくらでもお話しします。どうぞ一度、見にいらしてください。",
  "k322": "かみのて保育園 園長 兼松 香代美",
