  "k335": "株式会社 A and K（代表取締役 兼松 厚志）<br>〒509-0207 岐阜県可児市今渡3-11／TEL 0574-66-3511",
  "k336": "かみのて保育園／かみのて今渡保育園（認可）／病児保育／児童発達支援・放課後等デイサービス かみのてKIDS・かみのてSMILE／外国人材事業",
  "k337": "園のご紹介（2つの園）を見る →",
  "k338": "※ 保育理念・保育方針・保育目標・園長メッセージは、これまでにうかがったお話とトップページの言葉から組んだ<b>仮の案</b>です。実際の理念がすでにおありでしたら差し替えます。園・法人の概要は現行サイトからの引用です。",
  "k339": "これまでの経験を、",
  "k340": "ここで使ってください",
  "k341": "保育のしかたは園によってちがいます。<br class=\"x-br\">前の園のやり方を捨てていただく必要はありません。",
  "k342": "ブランクがあってもかまいません。",
  "k343": "数年ぶりの現場でも、はじめは短い時間から戻していけます。変わったところはこちらからお伝えします。",
  "k344": "ご自身の子育てと、両立できます。",
  "k345": "お子さんの行事やご家庭のご都合に合わせてシフトを組みます。時間や日数のご相談もお受けします。",
  "k346": "外国にルーツのある子の保育に関われます。",
  "k347": "英語・タガログ語・ビサヤ語・ポルトガル語に対応しています。ことばができなくても大丈夫です。関わり方は入ってから身につきます。",
  "k348": "働き方",
  "k349": "働き方は、2つから",
  "k350": "どちらもご相談のうえで決めます。<br class=\"x-br\">パートから正職員に変わった方もいます。",
  "k351": "正職員",
  "k352": "7:00〜20:00 のあいだのシフト制（実働8時間）。年間休日120日以上。クラスや行事の担当を持っていただきます。",
  "k353": "パート・時短",
  "k354": "週2日から、1日3時間から。朝だけ、夕方だけ、といった入り方もできます。お子さんの学校行事にも合わせられます。",
  "k355": "働き方は変えられます",
  "k356": "ご家庭の状況は変わります。時間を減らす・戻す、どちらのご相談もお受けしています。",
  "k357": "募集要項",
  "k358": "中途の募集について",
  "k359": "資格をお持ちでない方の保育補助も募集しています。",
