  "k384": "前の職場の引き継ぎに合わせます。急いでいただく必要はありません。",
  "k385": "<b>まずは話だけ聞いてみたい、でもかまいません。</b> すぐに転職するつもりがなくても、園のようすを知っておいていただくのは無駄になりません。見学だけで終わっても、こちらから連絡を重ねることはありません。",
  "k386": "※ 募集職種・勤務条件・入職までの流れは、デザイン案としての仮のものです。取材のときにうかがって差し替えます。",
  "k387": "園を見にきてください",
  "k388": "今のお仕事を続けながらでも、ご相談だけでもかまいません。<br class=\"x-br\">ご都合のよい時間に合わせます。",
  "k389": "園見学を申し込む",
  "k390": "新卒採用の方はこちら",
  "k391": "はじめの一歩を、",
  "k392": "いっしょに",
  "k393": "保育の仕事は、はじめから全部できる人はいません。<br class=\"x-br\">できるようになるまでを、園全体で支えます。",
  "k394": "1年目は、ひとりにしません。",
  "k395": "先輩とペアで動くところから始めます。分からないことを聞ける相手が、いつもとなりにいる状態をつくります。",
  "k396": "多言語の現場で、はじめから学べます。",
  "k397": "外国にルーツのあるご家庭が多く通っています。ことばや文化のちがう子とどう関わるかを、実際の毎日の中で学べます。",
  "k398": "ひとりの子を、じっくり見られます。",
  "k399": "定員30名の小さな園です。大人数をさばく仕事ではなく、一人ひとりの育ちに向き合う仕事です。",
  "k400": "1年目の育ち方",
