  "k556": "かみのて保育園は企業主導型保育園で、企業枠・地域枠があり、園へ直接お申し込みいただきます。かみのて今渡保育園は可児市の認可保育園で、市役所へのお申し込みが必要です。",
  "k557": "見学を受け付けています。こどもたちの生活時間に合わせてご案内するため、事前に電話またはお問い合わせフォームからご予約ください。入園時期が未定の方もご相談いただけます。",
  "k558": "かみのて保育園は、自社枠10,000円、提携企業枠25,000円、地域枠30,000円が月額の目安で、入園料はありません。かみのて今渡保育園は可児市が世帯状況などに応じて決定します。",
