  "k605": "見学はできますか",
  "k606": "保育時間は何時から何時までですか",
  "k607": "かみのて保育園は7:00〜20:00、かみのて今渡保育園は7:30〜19:30（土・祝は7:30〜16:30）です。18時からは延長保育となり、補食もご用意しています。",
  "k608": "病児保育はどのような場合に利用できますか",
  "k609": "熱が出たなどで、いつもの園や学校に行けない日に、専属の看護師と保育士がお預かりします。生後6ヵ月から小学校6年生までが対象で、他の園や小学校に通うお子さまもご利用いただけます。ご利用には事前登録と、かかりつけ医の診療情報提供書が必要です。",
