  "k622": "3件",
  "k623": "健康・安全",
  "k624": "ことば・文化",
  "k625": "<i>Q</i>入園はいつでも申し込めますか。<b></b>",
  "k626": "かみのて保育園は、空きがあれば年度の途中でもご入園いただけます。園へ直接お申し込みください。かみのて今渡保育園は可児市役所 保育課へのお申し込みとなり、受付時期が決まっています。",
  "k627": "<i>Q</i>2つの園は、何がちがうのですか。<b></b>",
  "k628": "<i>Q</i>見学はできますか。予約は必要ですか。<b></b>",
  "k629": "<i>Q</i>途中入園や、きょうだいでの入園はできますか。<b></b>",
  "k630": "空き状況によってご案内できます。きょうだいでの入園も含め、月ごとに受け入れ状況が変わるため、希望時期を添えてお問い合わせください。",
  "k631": "<i>Q</i>慣らし保育はありますか。<b></b>",
  "k632": "短い時間から始め、こどもの様子を見ながら少しずつ園で過ごす時間を延ばします。目安は1〜2週間ですが、ご家庭の予定やこどもの様子に合わせて調整します。",
  "k633": "<i>Q</i>何時から何時まで預かってもらえますか。<b></b>",
  "k634": "かみのて保育園：7:00〜20:00<br>かみのて今渡保育園：7:30〜19:30（土・祝は7:30〜16:30）",
  "k635": "18時からは延長保育となり、補食もご用意しています。",
  "k636": "<i>Q</i>給食はありますか。アレルギーには対応してもらえますか。<b></b>",
  "k637": "園内で調理した給食とおやつをご用意しています。食物アレルギーは医師の指示書に基づいて対応します。宗教や文化による食事の配慮もご相談ください。",
  "k638": "<i>Q</i>一時的に預けることはできますか。<b></b>",
  "k639": "かみのて今渡保育園で一時保育を行っています。対象は生後6か月〜2歳、利用時間は9:00〜16:00、利用料は1日2,500円です。事前登録が必要なため、0574-66-3511へお問い合わせください。",
  "k640": "<i>Q</i>送迎はありますか。<b></b>",
  "k641": "かみのて保育園ではご希望に応じて送迎をご案内しています。料金の目安は可児市内5,000円／月、市外6,000円／月です。地域や時間によって対応が異なるためご相談ください。",
  "k642": "<i>Q</i>持ちものは何が必要ですか。<b></b>",
  "k643": "着替え、おむつ、おしりふき、お昼寝用のバスタオルなどをご用意いただきます。年齢や利用内容に合わせて、入園時に詳しくご案内します。",
  "k644": "<i>Q</i>保育料はいくらですか。<b></b>",
  "k645": "<i>Q</i>保育料のほかに、かかるものはありますか。<b></b>",
  "k646": "行事費、教材費、送迎を利用する場合の費用などがかかることがあります。利用内容に合わせて事前にご説明します。",
  "k647": "<i>Q</i>提携企業の枠とは何ですか。<b></b>",
  "k648": "企業主導型保育園と利用契約を結んだ企業で働くご家庭向けの枠です。現在のお勤め先が提携していない場合も、手続きについてご案内できます。",
  "k649": "<i>Q</i>園で熱が出たときは、どうなりますか。<b></b>",
  "k650": "看護師が健康状態を確認し、保護者の方へご連絡します。病児保育室は生後6か月〜小学6年生が対象で、平日9:00〜17:00、1回2,000円で利用できます。事前登録と医療機関の情報が必要です。",
  "k651": "病児保育について見る →",
  "k652": "<i>Q</i>薬をあずかってもらえますか。<b></b>",
  "k653": "医師から処方された薬に限り、依頼書とともにお預かりします。市販薬はお預かりできません。",
  "k654": "<i>Q</i>防犯や災害への備えはどうなっていますか。<b></b>",
  "k655": "毎月の避難訓練、玄関の施錠、送迎者変更時の確認を行っています。災害時の連絡方法や引き渡しについても入園時にご案内します。",
  "k656": "<i>Q</i>日本語があまり話せません。それでも入園できますか。<b></b>",
  "k657": "ご入園いただけます。英語、タガログ語、ビサヤ語、ポルトガル語でのご案内や翻訳も行い、ご家庭とのやりとりを支えます。",
  "k658": "<i>Q</i>こどもが日本語をわからなくても大丈夫ですか。<b></b>",
  "k659": "大丈夫です。ご家庭で大切にしていることばを尊重しながら、遊びや生活を通して少しずつ日本語にふれられるよう支えます。",
  "k660": "<i>Q</i>宗教や文化のうえで、できないことがあります。<b></b>",
  "k661": "入園前の面談でお聞かせください。食事、行事、生活習慣など、ご家庭の考えを確認しながらできる範囲で対応します。",
  "k662": "<b>!</b><strong>回答の一部は確認前の仮案です。</strong>開所時間・保育料・送迎・一時預かり・病児保育・対応言語は現サイトの掲載情報をもとにしています。最新情報はお問い合わせください。",
  "k663": "ここに答えがないときは",
  "k664": "どんな小さなことでも、お気軽にご相談ください。",
