  "k729": "3つの保育方針",
  "k730": "理念を 毎日のかたちに",
  "k731": "一人ひとりのリズムに合わせる",
  "k732": "生活のリズムや発達のペースは、一人ひとりちがいます。こどものリズムにこちらが合わせ、ゆったりと関わります。",
  "k733": "ことばと文化のちがいを大切に",
  "k734": "ことばや育ってきた文化のちがいを前提に、一人ひとりの気持ちにていねいに耳を傾けます。",
  "k735": "ご家庭と 同じ側に立つ",
