  "k1058": "3歳〜5歳",
  "k1059": "3歳児〜5歳児を受け入れている、可児市の認可外保育園です。可児市内はもちろん、美濃加茂市・御嵩町・川辺町・坂祝町など近隣の市町村のお子さまも通えます。<b>送迎サービス</b>もありますので、ご希望の方はご相談ください。",
  "k1060": "フィリピン・ブラジル・ベトナム・ペルーなどにルーツを持つお子さまが通う、国際色豊かな保育園です。年少・年中は主に<b>英語のレッスン</b>、年長は小学校に向けて<b>日本語のレッスン</b>を行います。保育士・子育て支援員のほか、英語／タガログ語／ビサヤ語のスタッフ、ポルトガル語のスタッフがいます。",
  "k1061": "卒園して小学校に入ったあとも<b>学童保育</b>を行っています。小学校から学童保育所までの送迎もあります。",
