  "k1361": "卒園式☆（5歳児）",
  "k1362": "☆は保護者の方に参加をお願いする行事です。",
  "k1363": "感謝",
  "k1364": "誰に対しても、常に感謝の気持ちで接します。",
  "k1365": "誠実・真摯",
  "k1366": "誠実に、真摯に向き合います。",
  "k1367": "ていねい",
  "k1368": "丁寧な姿勢を大切にします。",
  "k1369": "祝日はお休み",
  "k1370": "A and K が運営する保育園に通うお子さまは無料",
  "k1371": "予約の先着順",
  "k1372": "当日のお預かり",
  "k1373": "健康チェック",
  "k1374": "1日の看護保育は、看護師と保育士が担当します。体温などの確認や様子の観察、体調に合わせた遊び、生活のお手伝いをします。",
  "k1375": "受け入れのとき・お迎え",
  "k1376": "受け入れの前に、病児保育室で検温と体の様子を確認しながら、保護者の方に病状をうかがいます",
  "k1377": "病状によってはお受けできない場合があります",
  "k1378": "お預かり中に病状が悪くなったときは、早めのお迎えをお願いすることがあります。必ず連絡が取れるようにしておいてください",
  "k1379": "お迎えは17:00までにお願いします",
  "k1380": "ご利用の目安",
  "k1381": "利用する日に満たしていること",
  "k1382": "体温が38.5℃以下",
  "k1383": "食事・水分・ミルクがとれて、脱水の症状がない",
  "k1384": "何度も吐いたり、ひどい下痢が続いたりしていない",
  "k1385": "ゼーゼー・ヒューヒューなど、呼吸が苦しい様子がない",
  "k1386": "お預かりできない場合",
  "k1387": "医師がお預かりできないと判断した場合",
  "k1388": "はしか・水ぼうそう・感染性胃腸炎など、ほかの人にうつる恐れが強い場合",
  "k1389": "38.5℃以上の熱が続いている",
  "k1390": "嘔吐・下痢がひどく、脱水の症状がある",
  "k1391": "咳がひどく、呼吸が苦しい（ぜんそくの発作を含む）",
  "k1392": "重い持病があり、感染すると重症になりやすい場合や、免疫を抑える薬を使っている場合",
  "k1393": "利用できる主な病気",
  "k1394": "かぜ・気管支炎・マイコプラズマ感染症・RSウイルス感染症・ヘルパンギーナ・手足口病・突発性発疹・ヒトメタニューモウイルス感染症・骨折・ねんざ など",
  "k1395": "症状が落ちついてから利用できる病気",
  "k1396": "新型コロナウイルス感染症・インフルエンザ",
  "k1397": "発症後4日を過ぎ、熱が下がっている",
  "k1398": "溶連菌咽頭炎",
  "k1399": "抗菌薬を飲みはじめたあと",
