  "k1401": "嘔吐や何度も続く・多量の下痢がなく、水分と食事がとれる",
  "k1402": "はしか・風しん・水ぼうそう・おたふくかぜ・咽頭結膜熱・流行性角結膜炎",
  "k1403": "学校保健で決められた出席停止の期間が過ぎたあと",
  "k1404": "※熱が下がっているとは、原則として解熱剤を使わずに、おおよそ37.5℃未満になっていることです。",
