  "k013": "Kani City, Gifu ・ Kaminote Nursery / Kaminote Imawatari Nursery",
  "k014": "Putting each child's ",
  "k015": "“I want to try”",
  "k016": "at the heart of every day.",
  "k017": "Mornings, evenings, and days when they are unwell.<br>We care for your child through the day, right beside working families.",
  "k018": "2 nurseries + sick-child room",
  "k019": "Company-led + licensed",
  "k020": "Multilingual support",
  "k021": "See admissions",
  "k022": "Opening hours, Kaminote Nursery",
  "k023": "Two nurseries and a sick-child room",
  "k024": "English, Tagalog, Bisaya, Portuguese",
  "k025": "Three reassurances",
  "k026": "Three reasons families choose Kaminote",
  "k027": "Open from 7 a.m. until 7:30 or 8 p.m.",
  "k028": "Kaminote Nursery is open 7:00–20:00 and Kaminote Imawatari Nursery 7:30–19:30. Early shift or late, we fit around how your family works.",
  "k029": "We care for children with a fever, too",
  "k030": "Our sick-child room, attached to Kaminote Nursery, cares for children from 6 months old to sixth grade. Children who attend other nurseries or schools can use it as well.",
  "k031": "We welcome you in many languages",
  "k032": "We support English, Tagalog, Bisaya and Portuguese. So that families with roots abroad can attend with confidence, our care starts from the assumption that cultures differ.",
  "k033": "Our childcare ―<br>what we hold to",
  "k034": "Children grow not by being taught, but by trying things for themselves. Our job is to make a place where that “I want to try” can appear, and to wait until they manage it.",
  "k035": "Care that waits.",
  "k036": "We hold back rather than step in, and share the moment they manage it themselves.",
  "k037": "Difference as the norm.",
  "k038": "Language, culture and pace of growth all differ. We make a place where children can be as they are.",
  "k039": "One team with your family.",
  "k040": "We tell you how the day went, every day, and think it through together.",
  "k041": "We run two nurseries",
  "k042": "Both welcome visits.",
  "k043": "Company-led nursery ／ 3-5 Imawatari, Kani, Gifu",
  "k044": "Hours",
  "k045": "Places",
  "k046": "30 children",
