  "k051": "Kaminote Imawatari Nursery",
  "k052": "Licensed nursery of Kani City ／ 3-11 Imawatari, Kani, Gifu",
  "k053": "7:30 − 19:30 (Mon–Fri)<br>7:30 − 16:30 (Sat &amp; holidays)",
  "k054": "Ages",
  "k055": "0 to 5 years",
  "k056": "Kani City Hall, Childcare Division",
  "k057": "Another option for the day a fever starts",
  "k058": "“I really cannot take today off.” On days like that, a dedicated nurse and childcare staff look after your child. <b>From 6 months old to sixth grade</b>, children who attend other nurseries or schools can use it too.",
  "k059": "One place a day, 9:00–17:00 (Mon–Fri), ¥2,000 per use. Advance registration and a medical information form from your family doctor are required.",
  "k060": "About sick-child care →",
  "k061": "Admissions and fees",
  "k062": "The two nurseries run under different systems, so you apply in different places. Please start from the nursery you have in mind.",
  "k063": "Kaminote Nursery (company-led)",
  "k064": "You can apply <b>direct to the nursery</b>, without going through the city office. Alongside community places, open regardless of where you live or work, there are places for employees of partner companies and for our own staff, each with different fees. There is no enrolment fee.",
  "k065": "1. Enquiry or phone call",
  "k066": "2. Visit and paperwork",
  "k067": "3. Start",
  "k068": "See fees and how to enrol →",
  "k069": "Kaminote Imawatari Nursery (licensed)",
  "k070": "This is a licensed nursery of Kani City. Applications are handled by the <b>Childcare Division at Kani City Hall</b>. After the city sends you the nursery information, please book a visit. Please check fees with the city office.",
  "k071": "1. To Kani City Hall",
  "k072": "2. Book a visit",
  "k073": "3. Visit, interview, apply",
  "k074": "See how to enrol →",
  "k075": "<b>Temporary care is also available.</b> At Kaminote Imawatari Nursery we look after children from 0 (6 months) to 2 years old for ¥2,500 a day (9:00–16:00, Mon–Sat and holidays). Advance registration is required.",
  "k076": "The people who work here",
  "k077": "It is the people here who support each child's day. Who they are, and what they care about. We have gathered a day in the job and interviews with our staff.",
  "k078": "120+ days",
  "k079": "Days off a year",
  "k080": "Languages spoken",
  "k081": "Shift system (hours)",
  "k082": "Places to work",
  "k083": "See careers",
  "k084": "News and nursery diary",
