  "k556": "Kaminote Nursery is a company-led nursery with partner-company and community places, and you apply direct to the nursery. Kaminote Imawatari Nursery is a licensed nursery of Kani City, and you apply through the city office.",
  "k557": "Yes, visits are welcome. We show you around at a time that fits the children’s day, so please book in advance by phone or through the enquiry form. You are welcome even if you have not decided when to start.",
  "k558": "At Kaminote Nursery the monthly fee is about ¥10,000 for staff places, ¥25,000 for partner-company places and ¥30,000 for community places, with no enrolment fee. At Kaminote Imawatari Nursery, Kani City sets the fee based on your household circumstances.",
