  "k598": "* This is one example. The day differs by age and nursery.",
  "k599": "So much<br>learning<br>in play",
  "k600": "Start with what you want to know",
  "k601": "Our thinking,<br>approach and features",
  "k602": "The daily routine, yearly events<br>and how children grow",
  "k603": "How to enrol, documents<br>and fees",
  "k604": "How to use it, who can use it<br>and the daily routine",
  "k605": "Can we visit?",
  "k606": "What are the opening hours?",
  "k607": "Kaminote Nursery is open 7:00–20:00 and Kaminote Imawatari Nursery 7:30–19:30 (7:30–16:30 on Saturdays and holidays). From 18:00 it is extended care, and we also provide a light snack.",
  "k608": "When can we use sick-child care?",
  "k609": "On days when your child cannot go to their usual nursery or school, for example because of a fever, our dedicated nurse and childcare staff look after them. It is for children from 6 months to 6th grade of elementary school, including those who attend other nurseries or schools. Advance registration and a referral letter from your family doctor are required.",
  "k610": "All FAQs →",
  "k611": "Why not come and feel",
  "k612": "our nursery for yourself?",
  "k613": "Questions or anything about enrolment —<br>please feel free to contact us.",
  "k614": "Photos are for illustration only",
  "k615": "About admission, daily life and costs —<br>start with whatever you want to know.",
  "k616": "Search the FAQ",
  "k617": "Search",
  "k618": "19 questions",
  "k619": "Admission and applying",
  "k620": "5",
  "k621": "Fees and costs",
  "k622": "3",
  "k623": "Health and safety",
  "k624": "Language and culture",
  "k625": "<i>Q</i>Can we apply at any time?<b></b>",
  "k626": "At Kaminote Nursery, children can start partway through the year if a place is free. Please apply direct to the nursery. For Kaminote Imawatari Nursery, you apply to the Childcare Division at Kani City Hall, and applications are accepted at set times.",
  "k627": "<i>Q</i>What is the difference between the two nurseries?<b></b>",
  "k628": "<i>Q</i>Can we visit? Do we need to book?<b></b>",
  "k629": "<i>Q</i>Can a child start mid-year, or siblings start together?<b></b>",
  "k630": "It depends on available places. Availability, including for siblings, changes month by month, so please contact us with the timing you have in mind.",
  "k631": "<i>Q</i>Is there a settling-in period?<b></b>",
  "k632": "We start with short stays and gradually extend the time at the nursery while watching how your child is doing. It usually takes 1–2 weeks, adjusted to your family’s schedule and your child.",
  "k633": "<i>Q</i>What hours can you look after my child?<b></b>",
  "k634": "Kaminote Nursery: 7:00–20:00<br>Kaminote Imawatari Nursery: 7:30–19:30 (7:30–16:30 on Saturdays and holidays)",
  "k635": "From 18:00 it is extended care, and we also provide a light snack.",
  "k636": "<i>Q</i>Do you provide lunch? Can you handle allergies?<b></b>",
  "k637": "We serve lunches and snacks cooked on site. Food allergies are handled according to a doctor’s instructions. Please also talk to us about dietary needs for religious or cultural reasons.",
  "k638": "<i>Q</i>Can we use temporary care?<b></b>",
  "k639": "Kaminote Imawatari Nursery offers temporary care for children from 6 months to 2 years, 9:00–16:00, for ¥2,500 a day. Advance registration is required, so please call 0574-66-3511.",
  "k640": "<i>Q</i>Do you offer pick-up and drop-off?<b></b>",
  "k641": "Kaminote Nursery can arrange pick-up and drop-off on request. As a guide, it costs ¥5,000 a month within Kani City and ¥6,000 a month outside. Arrangements vary by area and time, so please ask us.",
  "k642": "<i>Q</i>What do we need to bring?<b></b>",
  "k643": "Please prepare changes of clothes, nappies, wipes and a bath towel for naps, among other things. We will explain the details at enrolment, depending on age and how you use the nursery.",
  "k644": "<i>Q</i>How much are the fees?<b></b>",
  "k645": "<i>Q</i>Are there any costs besides the fees?<b></b>",
  "k646": "There may be costs for events, learning materials and pick-up/drop-off if you use it. We explain these in advance according to how you use the nursery.",
  "k647": "<i>Q</i>What are partner-company places?<b></b>",
  "k648": "These places are for families working at companies that have a usage agreement with the company-led nursery. If your employer is not a partner yet, we can explain the procedure.",
  "k649": "<i>Q</i>What happens if my child gets a fever at the nursery?<b></b>",
  "k650": "A nurse checks your child’s condition and contacts you. The sick-child care room is for children from 6 months to 6th grade, weekdays 9:00–17:00, ¥2,000 per use. Advance registration and medical information are required.",
  "k651": "About sick-child care →",
  "k652": "<i>Q</i>Can you give my child medicine?<b></b>",
  "k653": "Only medicine prescribed by a doctor, together with a request form. We cannot accept over-the-counter medicine.",
  "k654": "<i>Q</i>How do you prepare for security and disasters?<b></b>",
  "k655": "We hold evacuation drills every month, lock the entrance, and confirm whenever the person picking up changes. We also explain how we contact you and hand children over in a disaster at enrolment.",
  "k656": "<i>Q</i>I don’t speak much Japanese. Can my child still enrol?<b></b>",
  "k657": "Yes. We offer guidance and translation in English, Tagalog, Bisaya and Portuguese to support communication with your family.",
  "k658": "<i>Q</i>Is it okay if my child doesn’t understand Japanese?<b></b>",
  "k659": "Yes. While respecting the language your family values, we help children get used to Japanese little by little through play and daily life.",
  "k660": "<i>Q</i>There are things we cannot do for religious or cultural reasons.<b></b>",
  "k661": "Please tell us at the interview before enrolment. We will check your family’s wishes on meals, events and daily habits and accommodate them as far as we can.",
  "k662": "<b>!</b><strong>Some answers are provisional drafts.</strong> Opening hours, fees, pick-up/drop-off, temporary care, sick-child care and supported languages are based on the current website. Please contact us for the latest information.",
  "k663": "Can’t find your answer here?",
  "k664": "Please feel free to ask us anything, however small.",
