  "k705": "Both nurseries welcome visits.",
  "k706": "Our philosophy <small>PHILOSOPHY</small>",
  "k707": "Every child’s “I want to try”<br>at the heart of every day",
  "k708": "Starting from each child’s feelings,<br>we watch over their power to grow.",
  "k709": "Days that lead to “I’ll try it myself”",
  "k710": "We value a child’s wish to try, prepare an environment where they can try things themselves, and watch over them closely.<br>We share their joy when it goes well, and support their wish to try again when it doesn’t.",
