  "k727": "🍃<b>Enjoy differences</b>",
  "k728": "♡<b>Put feelings into words</b>",
  "k729": "Our 3 approaches",
  "k730": "Turning our philosophy into everyday practice",
  "k731": "Following each child’s rhythm",
  "k732": "Every child has their own daily rhythm and pace of development. We match their rhythm and spend time with them calmly.",
  "k733": "Valuing differences in language and culture",
  "k734": "Taking differences in language and upbringing as a given, we listen carefully to each child’s feelings.",
  "k735": "Standing on the same side as families",
  "k736": "We value daily conversation so that the nursery and families face the same way and support children’s growth together.",
  "k737": "See how we work each day",
  "k738": "Our 4 goals",
  "k739": "The growth we watch over",
  "k740": "Eat well, sleep well, play well",
  "k741": "Balancing meals, sleep and play, we build a foundation for mind and body.",
  "k742": "Think and try for themselves",
  "k743": "Valuing the wish to try, children build experience of thinking and trying things themselves.",
  "k744": "Enjoy differences",
  "k745": "Children see differences from friends and others as interesting and fun.",
  "k746": "Put feelings into words",
  "k747": "We help children express how they feel — happy, sad, or “I don’t like it”.",
  "k748": "Message from the head (draft)",
  "k749": "Raising children together with families",
  "k750": "We value each child’s wish to try, and want to watch over their power to grow in a place where they feel safe.",
  "k751": "We want the nursery to be a place both children and families can rely on with peace of mind. Valuing daily conversation, we support children’s growth together with families.",
  "k752": "Please come and see the nursery for yourself.",
  "k753": "Head of Kaminote Nursery",
  "k754": "Differences between the nurseries and facilities",
  "k755": "The daily routine and how children spend the day",
  "k756": "What we value",
  "k757": "Why not come and feel the nursery?",
  "k758": "See what we value in our actual daily care.",
  "k759": "The wording of our philosophy, approach, goals and message is being confirmed",
  "k760": "We value time for children to try things themselves,<br>wait until they can, and share the joy when they do.",
  "k761": "Waiting patiently",
  "k762": "Valuing differences",
  "k763": "Together with families",
  "k764": "3 things we value",
  "k765": "We believe in children’s “I want to try”<br>and watch over them until they can.",
  "k766": "Differences are normal",
  "k767": "We accept differences in language, culture<br>and pace of growth as they are.",
  "k768": "One team with families",
  "k769": "We share how children are doing at the nursery<br>and think about their growth together.",
  "k770": "Valuing the time until “I did it”",
  "k771": "We value and watch over children’s wish to try things themselves.<br>We don’t step in right away; we wait until they can, and share the joy of doing it themselves.",
  "k772": "Try it out",
  "k773": "Celebrate “I did it”",
  "k774": "Adults stay close, watch over and help when needed",
  "k775": "A place where differences belong",
  "k776": "Language, culture and pace of growth are different for every child.<br>We respect each background and create a place where every child can be themselves.",
