  "k1001": "For every family<br>its own peace of mind",
  "k1002": "Kaminote has two nurseries: a company-led nursery<br>and a licensed nursery.<br>Both welcome visits.",
  "k1003": "What’s happening<br>at the nursery",
  "k1004": "Event information, important notices<br>and the children’s everyday life —<br>news from Kaminote Nursery, as it happens.",
  "k1005": "Peace of mind<br>for your first nursery choice",
  "k1006": "A nursery that suits your child and family.<br>Kaminote has two nurseries:<br>a company-led nursery and a licensed nursery.<br>We explain how to apply and the fees<br>for each, simply and clearly.",
  "k1007": "Enrolment fee",
  "k1008": "None",
  "k1009": "Fees",
  "k1010": "A safe place to be<br>even on days they feel unwell",
  "k1011": "Our dedicated nurse and childcare staff stay close to<br>your child’s health and help them rest with peace of mind.",
  "k1012": "Ask about sick-child care",
  "k1013": "6 months to 6th grade",
  "k1014": "Mon–Fri 9:00–17:00",
  "k1015": "¥2,000 per use",
  "k1016": "1 child",
  "k1017": "What we value",
  "k1018": "Care by a nurse and childcare staff",
  "k1019": "Our dedicated nurse and childcare staff look after your child.",
  "k1020": "Children from other nurseries and schools too",
  "k1021": "Children who attend other nurseries or elementary schools can also use it.",
  "k1022": "From 6 months to 6th grade",
  "k1023": "For children from 6 months old to 6th grade of elementary school.",
  "k1024": "How to use the service",
  "k1025": "Advance registration",
  "k1026": "See your family doctor and prepare the documents",
  "k1027": "Contact us and confirm availability",
  "k1028": "Use the service",
  "k1029": "Before using the service",
  "k1030": "What you need",
  "k1031": "A referral letter from your family doctor",
  "k1032": "Ask us about using the service",
  "k1033": "Please contact us by phone or through the enquiry form.",
  "k1034": "When you’re worried about your child’s health<br>please talk to us first",
  "k1035": "Contact us about sick-child care",
  "k1036": "Sick-child care enquiries",
  "k1037": "We value each child’s wish to try, prepare a place where they can try things for themselves, and watch over them close by.",
  "k1038": "When it works, we celebrate together; when it doesn’t, we support the wish to try again.",
  "k1039": "Our philosophy",
  "k1040": "Kaminote Nursery is open 7:00–20:00. From 18:00 is extended care, with a light snack. From morning to evening, we support working families.",
  "k1041": "On days your child can’t go to their usual nursery or school, for example because of a fever, our dedicated nurse and childcare staff look after them.",
  "k1042": "We support 4 languages, and help children grow in families of every language and culture.",
  "k1043": "Our two nurseries",
  "k1044": "Capacity: 30 children",
  "k1045": "Apply directly to the nursery",
  "k1046": "7:30–19:30 (Sat. & holidays until 16:30)",
  "k1047": "Apply to the Childcare Division, Kani City Hall",
  "k1048": "Life at the nursery",
  "k1049": "All news",
  "k1050": "Why not come and see our nursery for yourself?",
  "k1051": "Around the nursery",
  "k1052": "We have three nurseries: a company-led nursery,<br>a licensed nursery and an unlicensed nursery.<br>All of them welcome visits.",
  "k1053": "Compare the 3 nurseries ↓",
  "k1054": "The 3 nurseries at a glance",
  "k1055": "Hands of God Kindergarten",
  "k1056": "Unlicensed nursery in Kani City",
  "k1057": "7:00–19:30 (Mon–Fri)",
  "k1058": "Ages 3–5",
  "k1059": "An unlicensed nursery in Kani City for children aged 3 to 5. Children from Kani and nearby towns such as Minokamo, Mitake, Kawabe and Sakahogi are welcome. We also offer a <b>pick-up and drop-off service</b> — please ask if you are interested.",
  "k1060": "A truly international nursery, with children whose roots are in the Philippines, Brazil, Vietnam, Peru and more. The younger classes mainly have <b>English lessons</b>, and the oldest class has <b>Japanese lessons</b> to prepare for elementary school. Besides childcare staff and child-rearing support staff, we have staff who speak English, Tagalog and Bisaya, and staff who speak Portuguese.",
  "k1061": "After graduating and starting elementary school, children can continue in our <b>after-school care</b>. We also provide transport from school to the after-school care facility.",
  "k1062": "1149-1 Imawatari, Kani, Gifu",
  "k1063": "Age 3: 20 children<br>Ages 4–5: 45 children",
  "k1064": "Meals for ages 3–5 (with certification): ¥6,000/month<br>After-school care: ¥2,500/day",
  "k1065": "Our three nurseries",
  "k1066": "Find the nursery that suits your child and family.<br>We have three nurseries: a company-led nursery,<br>a licensed nursery and an unlicensed nursery.<br>Here we explain how to apply and the fees<br>for each one, step by step.",
  "k1067": "3 nurseries",
  "k1068": "Choose from our 3 nurseries",
  "k1069": "Meals for ages 3–5 (with certification): ¥6,000/month",
  "k1070": "Fees (guide)",
  "k1071": "Meals, ages 3–5 (with certification)",
  "k1072": "¥6,000",
  "k1073": "per month",
  "k1074": "After-school care",
  "k1075": "¥2,500",
  "k1076": "per day",
