  "k1299": "For children who can attend 16 days or more a month (including sick days). Enrollment generally starts on the 1st of the month.",
  "k1300": "In months when your child attends 8 days or fewer because of illness or similar reasons, the fee is halved.",
  "k1301": "During Golden Week, Obon, the New Year holidays and public holidays, we care for children only when both parents are working (proof of employment required).",
