  "k1317": "Kaminote Imawatari Nursery offers temporary childcare for children aged 6 months to 2 years, 7:30–19:30 (Saturdays 8:00–16:30), for 2,500 yen per day. Advance registration is required, so please call 0574-66-3511.",
  "k1318": "Ages, hours and where to apply differ by nursery.",
  "k1319": "<b>Kaminote Nursery</b> We are accepting applications for the age-0 class for fiscal 2026 (Reiwa 8). Applications and visits for fiscal 2027 (Reiwa 9) are also welcome at any time.",
