  "k1363": "Gratitude",
  "k1364": "We treat everyone with gratitude at all times.",
  "k1365": "Sincerity",
  "k1366": "We face everything sincerely and earnestly.",
  "k1367": "Care",
  "k1368": "We value a careful, attentive attitude.",
  "k1369": "Closed on holidays",
  "k1370": "Free for children attending A and K nurseries",
  "k1371": "First come, first served",
  "k1372": "On the day",
  "k1373": "Health check",
  "k1374": "A nurse and a childcare worker look after your child all day. They check temperature, watch how your child is doing, offer play suited to their condition and help with daily routines.",
  "k1375": "Drop-off and pick-up",
  "k1376": "Before drop-off, we check your child’s temperature and condition in the sick-child room and ask you about their symptoms",
  "k1377": "Depending on the condition, we may not be able to accept your child",
  "k1378": "If your child’s condition gets worse, we may ask you to pick them up early. Please make sure we can always reach you",
  "k1379": "Please pick up your child by 17:00",
  "k1380": "Guidelines for use",
  "k1381": "Conditions on the day",
  "k1382": "Temperature of 38.5°C or lower",
  "k1383": "Can eat and drink (or take milk) with no signs of dehydration",
  "k1384": "No repeated vomiting or continued severe diarrhea",
  "k1385": "No signs of difficult breathing, such as wheezing",
  "k1386": "When we cannot accept your child",
  "k1387": "When a doctor decides the child should not be accepted",
  "k1388": "When there is a high risk of spreading illness to others, such as measles, chickenpox or infectious gastroenteritis",
  "k1389": "Fever of 38.5°C or higher continues",
  "k1390": "Severe vomiting or diarrhea with signs of dehydration",
  "k1391": "Severe cough with difficult breathing (including asthma attacks)",
  "k1392": "A serious chronic condition that makes infections dangerous, or use of immunosuppressive medicine",
  "k1393": "Main illnesses we can accept",
  "k1394": "Colds, bronchitis, mycoplasma, RSV, herpangina, hand-foot-and-mouth disease, roseola, human metapneumovirus, fractures, sprains, etc.",
  "k1395": "Illnesses accepted once symptoms settle",
  "k1396": "COVID-19 and influenza",
  "k1397": "More than 4 days after onset, with no fever",
  "k1398": "Strep throat",
  "k1399": "After starting antibiotics",
  "k1400": "Infectious gastroenteritis",
  "k1401": "No vomiting or repeated/heavy diarrhea, and able to eat and drink",
  "k1402": "Measles, rubella, chickenpox, mumps, pharyngoconjunctival fever, epidemic keratoconjunctivitis",
  "k1403": "After the school attendance suspension period set by school health rules",
  "k1404": "* “No fever” generally means below about 37.5°C without fever medicine.",
