  "k336": "Creche Kaminote / Creche Kaminote Imawatari (licenciada) / cuidado de crianças doentes / apoio ao desenvolvimento infantil e serviço após a escola (Kaminote KIDS e Kaminote SMILE) / serviços de mão de obra estrangeira",
  "k337": "Ver as duas creches →",
  "k338": "* A filosofia, os princípios, os objetivos e a mensagem da diretora são um <b>rascunho provisório</b>, montado a partir do que ouvimos até agora e das palavras da página inicial. Se vocês já tiverem os seus, substituiremos. O perfil da creche e da empresa foi citado do site atual.",
  "k339": "Use a experiência que você já tem",
  "k340": "aqui conosco",
  "k341": "Cada creche trabalha de um jeito.<br class=\"x-br\"> Você não precisa abandonar o método da creche anterior.",
  "k342": "Um período fora não é problema.",
  "k343": "Mesmo após alguns anos afastado, dá para voltar com jornada curta. Nós contamos o que mudou.",
  "k344": "Dá para conciliar com a criação dos seus filhos.",
  "k345": "Montamos a escala considerando os eventos escolares dos seus filhos e as necessidades da família. Horários e dias podem ser conversados.",
  "k346": "Você pode trabalhar com crianças de origem estrangeira.",
  "k347": "Atendemos em inglês, tagalo, cebuano e português. Não é preciso falar esses idiomas: a forma de se aproximar se aprende aqui dentro.",
  "k348": "Formas de trabalhar",
  "k349": "Duas formas de trabalhar",
  "k350": "Qualquer uma delas é combinada com você antes.<br class=\"x-br\"> Parte da equipe começou meio período e passou a efetiva.",
  "k351": "Efetivo",
  "k352": "Turnos entre 7h e 20h (8 horas efetivas). Mais de 120 dias de folga por ano. Você assume uma turma e eventos.",
  "k353": "Meio período e jornada reduzida",
  "k354": "A partir de dois dias por semana e de três horas por dia. Só de manhã ou só à tarde também é possível. Dá para acompanhar os eventos escolares dos seus filhos.",
  "k355": "Sua forma de trabalhar pode mudar",
  "k356": "As circunstâncias familiares mudam. Fale conosco sobre reduzir ou voltar a aumentar a jornada: as duas coisas são possíveis.",
  "k357": "Detalhes da vaga",
  "k358": "Vagas para profissionais experientes",
  "k359": "Também aceitamos auxiliares de creche sem formação específica.",
  "k360": "Cargo",
