  "k382": "Apresentamos por escrito a forma de trabalho e as condições.",
  "k383": "Definição da data de início",
  "k384": "Nós nos adaptamos à passagem de trabalho no seu emprego atual. Não há pressa.",
  "k385": "<b>Tudo bem vir apenas para ouvir sobre a vaga.</b> Mesmo sem planos de mudar de emprego agora, conhecer a creche nunca é tempo perdido. Se a visita ficar só nisso, não ficaremos entrando em contato.",
  "k386": "* As vagas, as condições e o processo de entrada são provisórios, escritos para este rascunho de design. Serão substituídos após as entrevistas.",
  "k387": "Venha conhecer a creche",
  "k388": "Você pode vir mesmo estando empregado, e uma conversa já basta.<br class=\"x-br\"> Marcamos no horário que for melhor para você.",
  "k389": "Agendar uma visita",
