  "k391": "Dê o primeiro passo",
  "k392": "conosco",
  "k393": "Ninguém dá conta deste trabalho desde o primeiro dia.<br class=\"x-br\"> A creche inteira apoia você até que consiga.",
  "k394": "No primeiro ano, você nunca fica sozinho.",
  "k395": "Você começa em dupla com um colega mais experiente. Garantimos que sempre haja alguém ao lado para perguntar.",
  "k396": "Você aprende num ambiente multilíngue desde o início.",
  "k397": "Muitas famílias aqui têm origem estrangeira. Você aprende a se relacionar com crianças de outros idiomas e culturas no meio do dia a dia.",
  "k398": "Você consegue acompanhar de perto cada criança.",
  "k399": "Somos uma creche pequena, com 30 vagas. Não é um trabalho de administrar multidões, é de acompanhar o crescimento de cada criança.",
  "k400": "Como você cresce no primeiro ano",
