  "k555": "É preciso cadastro prévio",
  "k556": "A Creche Kaminote é de iniciativa empresarial, com vagas para empresas parceiras e para a comunidade, e a inscrição é feita direto na creche. A Creche Kaminote Imawatari é uma creche licenciada da cidade de Kani, e a inscrição é feita na prefeitura.",
  "k557": "Sim, recebemos visitas. Como a visita é feita de acordo com a rotina das crianças, agende antes por telefone ou pelo formulário de contato. Mesmo sem data de início definida, fale conosco.",
  "k558": "Na Creche Kaminote a mensalidade de referência é ¥10.000 para funcionários, ¥25.000 para empresas parceiras e ¥30.000 para a comunidade, sem taxa de matrícula. Na Creche Kaminote Imawatari, a cidade de Kani define o valor conforme a situação da família.",
