  "k605": "Podemos visitar?",
  "k606": "Qual é o horário?",
  "k607": "A Creche Kaminote funciona das 7h às 20h e a Creche Kaminote Imawatari das 7h30 às 19h30 (aos sábados e feriados, das 7h30 às 16h30). A partir das 18h é horário estendido, com lanche leve.",
  "k608": "Quando posso usar o cuidado para crianças doentes?",
  "k609": "Nos dias em que a criança não pode ir à creche ou à escola, por exemplo por febre, uma enfermeira e educadoras dedicadas cuidam dela. É para crianças de 6 meses até o 6º ano do ensino fundamental, inclusive de outras creches e escolas. É preciso cadastro prévio e uma carta de encaminhamento do médico da família.",
