  "k619": "Matrícula e inscrição",
  "k620": "5",
  "k621": "Mensalidades e custos",
  "k622": "3",
  "k623": "Saúde e segurança",
  "k624": "Idioma e cultura",
  "k625": "<i>Q</i>Posso me inscrever a qualquer momento?<b></b>",
  "k626": "Na Creche Kaminote, a criança pode entrar no meio do ano se houver vaga. Faça a inscrição direto na creche. Para a Creche Kaminote Imawatari, a inscrição é feita na Divisão de Creches da Prefeitura de Kani, em períodos definidos.",
  "k627": "<i>Q</i>Qual é a diferença entre as duas creches?<b></b>",
  "k628": "<i>Q</i>Podemos visitar? É preciso agendar?<b></b>",
  "k629": "<i>Q</i>É possível entrar no meio do ano ou matricular irmãos juntos?<b></b>",
  "k630": "Depende das vagas. A disponibilidade, inclusive para irmãos, muda a cada mês; entre em contato informando quando deseja começar.",
  "k631": "<i>Q</i>Existe um período de adaptação?<b></b>",
  "k632": "Começamos com pouco tempo e aumentamos aos poucos, observando a criança. Em geral leva de 1 a 2 semanas, ajustando à agenda da família e à criança.",
  "k633": "<i>Q</i>Em que horário vocês cuidam da criança?<b></b>",
  "k634": "Creche Kaminote: 7h–20h<br>Creche Kaminote Imawatari: 7h30–19h30 (sábados e feriados: 7h30–16h30)",
  "k635": "A partir das 18h é horário estendido, com lanche leve.",
  "k636": "<i>Q</i>Há almoço? Vocês atendem alergias?<b></b>",
  "k637": "Servimos almoço e lanches preparados na própria creche. Alergias alimentares são atendidas conforme orientação médica. Fale conosco também sobre restrições por religião ou cultura.",
  "k638": "<i>Q</i>É possível deixar a criança temporariamente?<b></b>",
  "k639": "A Creche Kaminote Imawatari oferece cuidado temporário para crianças de 6 meses a 2 anos, das 9h às 16h, por ¥2.500 ao dia. É preciso cadastro prévio; ligue para 0574-66-3511.",
  "k640": "<i>Q</i>Vocês oferecem transporte?<b></b>",
  "k641": "A Creche Kaminote pode oferecer transporte a pedido. Valores de referência: ¥5.000/mês dentro de Kani e ¥6.000/mês fora. Depende da região e do horário; consulte-nos.",
  "k642": "<i>Q</i>O que é preciso levar?<b></b>",
  "k643": "Roupas para troca, fraldas, lenços umedecidos, toalha para o cochilo, entre outros. Explicamos os detalhes na matrícula, conforme a idade e o uso.",
  "k644": "<i>Q</i>Quanto custa a mensalidade?<b></b>",
  "k645": "<i>Q</i>Há outros custos além da mensalidade?<b></b>",
  "k646": "Pode haver custos de eventos, materiais e transporte, se utilizado. Explicamos antes, conforme o uso.",
  "k647": "<i>Q</i>O que são vagas de empresas parceiras?<b></b>",
  "k648": "São vagas para famílias que trabalham em empresas com contrato com a creche de iniciativa empresarial. Se a sua empresa ainda não é parceira, explicamos o procedimento.",
  "k649": "<i>Q</i>O que acontece se a criança tiver febre na creche?<b></b>",
  "k650": "Uma enfermeira verifica o estado da criança e avisa os responsáveis. A sala para crianças doentes atende de 6 meses ao 6º ano, dias úteis das 9h às 17h, por ¥2.000 por uso. É preciso cadastro prévio e informações médicas.",
  "k651": "Sobre o cuidado para crianças doentes →",
  "k652": "<i>Q</i>Vocês podem dar remédio à criança?<b></b>",
  "k653": "Apenas remédios receitados por médico, com formulário de solicitação. Não aceitamos remédios sem receita.",
  "k654": "<i>Q</i>Como vocês se preparam para segurança e desastres?<b></b>",
  "k655": "Fazemos simulados de evacuação todo mês, trancamos a entrada e confirmamos quando muda a pessoa que busca a criança. Na matrícula explicamos também o contato e a entrega das crianças em caso de desastre.",
  "k656": "<i>Q</i>Não falo muito japonês. Mesmo assim posso matricular?<b></b>",
  "k657": "Sim. Oferecemos orientação e tradução em inglês, tagalo, bisaya e português para apoiar a comunicação com a família.",
  "k658": "<i>Q</i>Tudo bem se a criança não entender japonês?<b></b>",
  "k659": "Sim. Respeitando o idioma da família, ajudamos a criança a conhecer o japonês aos poucos, nas brincadeiras e na rotina.",
  "k660": "<i>Q</i>Há coisas que não podemos fazer por religião ou cultura.<b></b>",
  "k661": "Conte-nos na entrevista antes da matrícula. Verificamos as preferências da família sobre alimentação, eventos e hábitos e atendemos dentro do possível.",
  "k662": "<b>!</b><strong>Algumas respostas são rascunhos provisórios.</strong> Horários, mensalidades, transporte, cuidado temporário, cuidado para crianças doentes e idiomas foram baseados no site atual. Consulte-nos para informações atualizadas.",
  "k663": "Não encontrou a resposta?",
  "k664": "Fale conosco sobre qualquer dúvida, por menor que seja.",
