  "k983": "As etapas da seleção e os documentos serão explicados após confirmação.",
  "k984": "Dúvidas antes de mudar de emprego ou voltar",
  "k985": "Perguntas que recebemos com frequência.",
  "k986": "Candidatura depois de um tempo afastado",
  "k987": "Se você ficou um tempo afastado, fale conosco primeiro. Vamos ouvir sobre sua experiência e a forma de trabalho que deseja.",
  "k988": "Conversar sobre horário e dias",
  "k989": "Conte o horário, os dias e a data de início desejados. Conversamos de acordo com as vagas atuais.",
  "k990": "Visitar ainda empregado",
  "k991": "Mesmo empregado, você pode pedir para visitar a creche. Consulte-nos sobre datas e horários.",
  "k992": "Requisitos e documentos",
  "k993": "Os requisitos e documentos de cada função serão explicados após confirmação. Consulte-nos sobre as vagas atuais.",
  "k994": "O próximo passo<br>começa com uma conversa",
  "k995": "O <em>“quero tentar”</em><br>de cada criança<br>no centro de tudo",
  "k996": "Mais sobre esta creche",
  "k997": "Comparar as creches",
  "k998": "Como chegar",
  "k999": "Ver mapa",
  "k1000": "Esperamos por você",
  "k1001": "Para cada família<br>a sua tranquilidade",
  "k1002": "A Kaminote tem duas creches: uma de iniciativa empresarial<br>e uma creche licenciada.<br>As duas recebem visitas.",
  "k1003": "O que acontece<br>na creche",
  "k1004": "Avisos de eventos, comunicados importantes<br>e o dia a dia das crianças:<br>o “agora” da Creche Kaminote.",
  "k1005": "Tranquilidade<br>na primeira escolha da creche",
  "k1006": "Uma creche que combine com a criança e a família.<br>A Kaminote tem duas creches:<br>uma de iniciativa empresarial e uma licenciada.<br>Explicamos de forma simples<br>a inscrição e as mensalidades de cada uma.",
  "k1007": "Taxa de matrícula",
  "k1008": "Nenhuma",
  "k1009": "Mensalidade",
  "k1010": "Um lugar seguro<br>mesmo nos dias de mal-estar",
  "k1011": "Uma enfermeira e educadoras dedicadas acompanham<br>a saúde da criança e cuidam dela com tranquilidade.",
  "k1012": "Perguntar sobre o cuidado para crianças doentes",
  "k1013": "6 meses ao 6º ano",
