  "k1017": "O que valorizamos",
  "k1018": "Cuidado por enfermeira e educadoras",
  "k1019": "Uma enfermeira e educadoras dedicadas cuidam da criança.",
  "k1020": "Também para crianças de outras creches e escolas",
  "k1021": "Crianças de outras creches ou escolas também podem usar.",
  "k1022": "De 6 meses ao 6º ano",
  "k1023": "Para crianças de 6 meses até o 6º ano do ensino fundamental.",
  "k1024": "Como utilizar",
