  "k1031": "Carta de encaminhamento do médico da família",
  "k1032": "Fale conosco sobre a utilização",
  "k1033": "Fale conosco por telefone ou pelo formulário de contato.",
  "k1034": "Quando a saúde da criança preocupar<br>fale conosco primeiro",
  "k1035": "Contato sobre o cuidado para crianças doentes",
  "k1036": "Contato do cuidado para crianças doentes",
  "k1037": "Valorizamos a vontade de tentar de cada criança, preparamos um ambiente para ela experimentar sozinha e acompanhamos de perto.",
  "k1038": "Quando dá certo, comemoramos juntos; quando não dá, apoiamos a vontade de tentar de novo.",
  "k1039": "Nossa filosofia",
  "k1040": "A Creche Kaminote funciona das 7h às 20h. A partir das 18h é horário estendido, com lanche leve. Da manhã à noite, apoiamos as famílias que trabalham.",
  "k1041": "Nos dias em que a criança não pode ir à creche ou à escola, por exemplo por febre, uma enfermeira e educadoras dedicadas cuidam dela.",
  "k1042": "Atendemos em 4 idiomas e apoiamos o crescimento das crianças de famílias de diferentes idiomas e culturas.",
  "k1043": "Nossas duas creches",
  "k1044": "Capacidade: 30 crianças",
  "k1045": "Inscrição direto na creche",
  "k1046": "7h30–19h30 (sábados e feriados até 16h30)",
  "k1047": "Inscrição na Divisão de Creches da Prefeitura de Kani",
  "k1048": "A vida na creche",
  "k1049": "Todas as notícias",
  "k1050": "Que tal vir conhecer o clima da nossa creche?",
  "k1051": "Um pouco da creche",
  "k1052": "Temos três creches: uma creche de iniciativa empresarial,<br>uma creche licenciada e uma creche não licenciada.<br>Todas aceitam visitas.",
  "k1053": "Comparar as 3 creches ↓",
  "k1054": "As 3 creches em resumo",
  "k1055": "Creche Hands of God",
  "k1056": "Creche não licenciada da cidade de Kani",
  "k1057": "7h–19h30 (seg–sex)",
  "k1058": "3 a 5 anos",
  "k1059": "Creche não licenciada da cidade de Kani para crianças de 3 a 5 anos. Atende crianças de Kani e de cidades vizinhas como Minokamo, Mitake, Kawabe e Sakahogi. Também oferecemos <b>serviço de transporte</b> — consulte-nos se tiver interesse.",
  "k1060": "Uma creche multicultural, com crianças com raízes nas Filipinas, no Brasil, no Vietnã, no Peru e em outros países. As turmas menores têm principalmente <b>aulas de inglês</b>, e a turma mais velha tem <b>aulas de japonês</b> para se preparar para a escola. Além de educadoras e auxiliares, temos funcionários que falam inglês, tagalo e bisaya, e funcionários que falam português.",
  "k1061": "Depois de se formar e entrar na escola, a criança pode continuar no nosso <b>cuidado pós-escola</b>. Também levamos as crianças da escola até o local do cuidado pós-escola.",
  "k1062": "Imawatari 1149-1, Kani, Gifu",
  "k1063": "3 anos: 20 crianças<br>4–5 anos: 45 crianças",
  "k1064": "Refeições para 3–5 anos (com certificação): ¥6.000/mês<br>Pós-escola: ¥2.500/dia",
  "k1065": "Nossas três creches",
  "k1066": "Encontre a creche ideal para sua criança e família.<br>Temos três creches: uma de iniciativa empresarial,<br>uma licenciada e uma não licenciada.<br>Explicamos como se inscrever e as mensalidades<br>de cada uma, passo a passo.",
